pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, uint256 amount) public {
        // 1. keep the domain wide; no restrictive assumptions needed
        vm.assume(to != address(0));

        // 2. adversarial environment: a token whose transferFrom always succeeds
        OkToken token = new OkToken();
        address[] memory tos = new address[](1);
        tos[0] = to;

        // 3. drive c through transfer and assert the returned success flag
        bool ok = c.transfer(from, address(token), tos, amount);
        assertTrue(ok);
    }
}

// minimal adversarial/succeeding counterparty: transferFrom succeeds (returns true)
contract OkToken {
    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encode(true);
    }
}
